INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(34211, 'Mark 10:50', 'Mark', 10, 50, 'نو هغه خپله چپنه یوې خواته وغورځوله، د خپل ځای څخه راپورته شو او عیسی ته راغی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark10_verse_50.mp3', '', 1761754199, 1761754199),
(34212, 'Mark 10:51', 'Mark', 10, 51, 'عیسی هغه ته وویل: «زما څخه څه غواړې چې درته ویې کړم؟» هغه ړوند سړي ځواب ورکړ: «زما استاذه، زه غواړم چې بېرته بینا شم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark10_verse_51.mp3', '', 1761754199, 1761754199),
(34213, 'Mark 10:52', 'Mark', 10, 52, 'عیسی هغه ته وویل: «ځه، ته خپل ایمان روغ کړې.» نو سمدلاسه هغه بینا شو او په عیسی پسې روان شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark10_verse_52.mp3', '', 1761754199, 1761754199),
(34214, 'Acts 10:1', 'Acts', 10, 1, 'په قیصریه کې یو سړی ؤ چې کورنیلیوس نومېده او د رومي لښکرو د کنډک چې د «ایټالوي کنډک» په نوم یادېده، مشر ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_1.mp3', '', 1761754199, 1761754199),
(34215, 'Acts 10:2', 'Acts', 10, 2, 'کورنیلیوس او د هغه کورنۍ دینداره خلک وو او د خدای څخه وېرېدل. هغه به غریبو یهودیانو ته ډېر خیراتونه ورکول او تل به یې دعا کوله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_2.mp3', '', 1761754199, 1761754199),
(34216, 'Acts 10:3', 'Acts', 10, 3, 'یوه ورځ د ماسپښین شاوخوا درې بجې هغه رویا ولیدله چې د خدای فرښته د هغه خواته راغله او ورته ویې ویل: «ای کورنیلیوسه!»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_3.mp3', '', 1761754199, 1761754199),
(34217, 'Acts 10:4', 'Acts', 10, 4, 'هغه له وېرې په ځیر سره فرښتې ته وکتل او پوښتنه یې ترې وکړه: «ښاغلیه څه وایې؟» فرښتې ځواب ورکړ: «ستا دعاګانې او خیراتونه چې تا ورکړي وو، هغه د خدای حضور ته ورسېدل او قبول یې کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_4.mp3', '', 1761754199, 1761754199),
(34218, 'Acts 10:5', 'Acts', 10, 5, 'اوس یو څو کسان یافا ته د شمعون پسې چې پطروس ورته ویل کیږي، ولېږه چې هغه راولي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_5.mp3', '', 1761754199, 1761754199),
(34219, 'Acts 10:6', 'Acts', 10, 6, 'هغه د شمعون څرمن جوړوونکي په کور کې چې د بحیرې په غاړه دی، مېلمه دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_6.mp3', '', 1761754199, 1761754199),
(34220, 'Acts 10:7', 'Acts', 10, 7, 'کله چې هغې فرښتې د هغه سره خبرې وکړې نو لاړه، بیا کورنیلیوس خپل دوه نوکران او یو عسکر چې یو دینداره سړی ؤ او د هغه د کور د خدمتګارانو څخه ؤ، راوغوښتل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_7.mp3', '', 1761754199, 1761754199),
(34221, 'Acts 10:8', 'Acts', 10, 8, 'هرڅه چې شوي وو، هغوی ته یې وویل او هغوی یې یافا ته ولېږل. پطروس رویا ویني', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_8.mp3', '', 1761754199, 1761754199),
(34222, 'Acts 10:9', 'Acts', 10, 9, 'بله ورځ د غرمې په وخت کې چې هغه دوه نوکران او عسکر په لاره کې روان وو او یافا ته ورسېدل، نو په همدې وخت کې پطروس د دعا کولو دپاره پاس بام ته وخوت.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_9.mp3', '', 1761754199, 1761754199),
(34223, 'Acts 10:10', 'Acts', 10, 10, 'هغه وږی شو او غوښتل یې چې څه وخوري، کله چې ډوډۍ تیارېدله، نو هغه رویا ولیدله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_10.mp3', '', 1761754199, 1761754199),
(34224, 'Acts 10:11', 'Acts', 10, 11, 'هغه ولیدل چې د اسمان دروازې خلاصې شوې او د یو لوی دسترخوان په شان یو شی چې د څلورو څنډو څخه راځوړند ؤ او ښکته د ځمکې خواته راروان ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_11.mp3', '', 1761754199, 1761754199),
(34225, 'Acts 10:12', 'Acts', 10, 12, 'په هغه کې هر ډول حیوانات، خزندې او مرغان وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_12.mp3', '', 1761754199, 1761754199),
(34226, 'Acts 10:13', 'Acts', 10, 13, 'بیا یو اواز راغی او هغه ته یې وویل: «ای پطروسه، پاڅېږه! هغه حلال کړه او ویې خوره.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_13.mp3', '', 1761754199, 1761754199),
(34227, 'Acts 10:14', 'Acts', 10, 14, 'خو پطروس وویل: «څښتنه! هېڅکله نه، ما هېڅکله هم حرام او ناپاکه شی نه دی خوړلی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_14.mp3', '', 1761754199, 1761754199),
(34228, 'Acts 10:15', 'Acts', 10, 15, 'په دوهم ځل بیا اواز راغی: «کوم شیان چې خدای حلال ګرځولي دي، هغه حرام مه ګڼه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_15.mp3', '', 1761754199, 1761754199),
(34229, 'Acts 10:16', 'Acts', 10, 16, 'درې ځلې همداسې وشول او بیا هغه دسترخوان بېرته پورته اسمان ته یووړل شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_16.mp3', '', 1761754199, 1761754199),
(34230, 'Acts 10:17', 'Acts', 10, 17, 'پطروس حیران پاتې ؤ چې د دې رویا معنی څه ده، چې په دې وخت کې هغو کسانو چې کورنیلیوس لېږلي وو، د شمعون کور پیدا کړ او هغوی د دروازې په مخکې ودرېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_17.mp3', '', 1761754199, 1761754199),
(34231, 'Acts 10:18', 'Acts', 10, 18, 'هغوی نارې کړې او پوښتنه یې وکړه: «ایا شمعون چې پطروس ورته هم وایي، دلته مېلمه دی؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_18.mp3', '', 1761754199, 1761754199),
(34232, 'Acts 10:19', 'Acts', 10, 19, 'پطروس لا د دې رویا په هکله فکر کاوه چې روح القدس ورته وویل: «ګوره، درې سړي تا لټوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_19.mp3', '', 1761754199, 1761754199),
(34233, 'Acts 10:20', 'Acts', 10, 20, 'پاڅېږه او لاندې راښکته شه او د هغوی سره په تللو کې زړه نازړه کېږه مه، ځکه چې هغوی ما درلېږلي دي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_20.mp3', '', 1761754199, 1761754199),
(34234, 'Acts 10:21', 'Acts', 10, 21, 'نو پطروس لاندې ښکته شو او هغوی ته یې وویل: «زه هماغه سړی یم چې تاسو یې لټوئ. تاسو د څه دپاره راغلي یئ؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_21.mp3', '', 1761754199, 1761754199),
(34235, 'Acts 10:22', 'Acts', 10, 22, 'هغوی ځواب ورکړ: «مونږ قوماندان کورنیلیوس رالېږلي یو. هغه یو نېک او داسې سړی دی چې له خدایه وېریږي او د ټولو یهودیانو په نظر کې ډېر عزتمن سړی دی. د خدای فرښتې هغه ته ویلي وو چې تا خپل کور ته راوغواړي او څه چې وایې هغه یې واوري.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_22.mp3', '', 1761754199, 1761754199),
(34236, 'Acts 10:23', 'Acts', 10, 23, 'نو پطروس هغوی کور ته راوستل او مېلمانه یې کړل. د کورنیلیوس او پطروس لیدنه بله ورځ پطروس پاڅېده او د هغوی سره روان شو او د یافا څو ایمانداران هم ورسره ملګري وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_23.mp3', '', 1761754199, 1761754199),
(34237, 'Acts 10:24', 'Acts', 10, 24, 'په بله ورځ هغوی قیصریې ته ورسېدل. کورنیلیوس هغوی ته په تمه ؤ او خپل خپلوان او خپل نژدې ملګري یې هم راغوښتي وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_24.mp3', '', 1761754199, 1761754199),
(34238, 'Acts 10:25', 'Acts', 10, 25, 'څنګه چې پطروس کور ته ورننوت، کورنیلیوس د هغه مخې ته ورووت او د هغه په پښو کې پرېوت او سجده یې ورته وکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_25.mp3', '', 1761754199, 1761754199),
(34239, 'Acts 10:26', 'Acts', 10, 26, 'خو پطروس هغه د ځمکې څخه راپورته کړ او ورته ویې ویل: «راپاڅېږه، زه هم ستا په شان یو انسان یم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_26.mp3', '', 1761754199, 1761754199),
(34240, 'Acts 10:27', 'Acts', 10, 27, 'په داسې حال کې چې پطروس د هغه سره خبرې کولې، کور ته ننوت او ویې لیدل چې هلته ډېر خلک راټول شوي وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_27.mp3', '', 1761754199, 1761754199),
(34241, 'Acts 10:28', 'Acts', 10, 28, 'پطروس هغوی ته وویل: «تاسو ته ښه معلومه ده چې د یهودیانو دپاره دا ناروا ده چې د غیریهودیانو سره ناسته ولاړه او یا ملګرتیا وکړي. خو خدای ماته دا راښودلي دي چې زه باید هېڅوک هم ناپاکه او نجس ونه ګڼم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_28.mp3', '', 1761754199, 1761754199),
(34242, 'Acts 10:29', 'Acts', 10, 29, 'کله چې زه تاسو راوغوښتلم، نو پرته له کوم اعتراضه راغلم. خو اوس پوښتنه کوم چې تاسو ولې زه راوغوښتلم؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_29.mp3', '', 1761754199, 1761754199),
(34243, 'Acts 10:30', 'Acts', 10, 30, 'کورنیلیوس وویل: «څلور ورځې کیږي چې په همدې وخت کې یعنې د ماسپښین په درې بجو زه په خپل کور کې په دعا کولو بوخت وم چې ناڅاپه یو سړی چې ځلېدونکي کالي یې اغوستي وو، زما په مخکې ودرېده', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_30.mp3', '', 1761754199, 1761754199),
(34244, 'Acts 10:31', 'Acts', 10, 31, 'او ویې ویل: ‹ای کورنیلیوسه! خدای ستا دعاګانې قبولې کړې دي او هغه خیراتونه یې قبول کړي دي چې غریبانو ته یې ورکوې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_31.mp3', '', 1761754199, 1761754199),
(34245, 'Acts 10:32', 'Acts', 10, 32, 'اوس یو څو کسان د شمعون پسې چې پطروس ورته ویل کیږي، یافا ته ولېږه چې هغه راولي. هغه د بحیرې په غاړه د شمعون څرمن جوړوونکي په کور کې مېلمه دی.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_32.mp3', '', 1761754199, 1761754199),
(34246, 'Acts 10:33', 'Acts', 10, 33, 'نو سمدلاسه مې تا پسې سړي درولېږل او تا ډېر ښه کار وکړ چې دلته راغلې. نو اوس مونږ ټول دلته د خدای په حضور کې حاضر یو چې د هرڅه په هکله چې څښتن تاته حکم کړی دی، هغه واورو.» غیریهودیانو ته د پطروس وینا', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_33.mp3', '', 1761754199, 1761754199),
(34247, 'Acts 10:34', 'Acts', 10, 34, 'پطروس خپلې خبرې پیل کړې او ویې ویل: «زه اوس پوه شوم چې دا رښتیا دي چې خدای د هېچا طرفداري نه کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_34.mp3', '', 1761754199, 1761754199),
(34248, 'Acts 10:35', 'Acts', 10, 35, 'په هر قوم کې چې هرڅوک ‎له خدایه وېریږي او سم کارونه کوي، خدای هغه مني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_35.mp3', '', 1761754199, 1761754199),
(34249, 'Acts 10:36', 'Acts', 10, 36, 'تاسو پوهېږئ چې خدای خپل پیغام د اسراییلو قوم ته ورولېږه او د سولې او سلامتۍ زېری یې د عیسی مسیح په وسیله چې د ټولو څښتن دی، اعلان کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_36.mp3', '', 1761754199, 1761754199),
(34250, 'Acts 10:37', 'Acts', 10, 37, 'تاسو پوهېږئ چې په ټوله یهودیه کې څه وشول. دا پېښه د یحیی د تعمید د غسل د اعلانولو څخه وروسته له جلیل څخه پیل شوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_37.mp3', '', 1761754199, 1761754199),
(34251, 'Acts 10:38', 'Acts', 10, 38, 'او تاسو خبر یئ چې خدای څنګه ناصري عیسی په روح القدس او په خپل قدرت سره مسح کړ. هغه به هرځای ته تللو او د خلکو سره به یې نېکي کوله او کوم خلک چې د شیطان په بند کې وو هغوی ته به یې شفا ورکوله، ځکه چې خدای ورسره مل ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_38.mp3', '', 1761754199, 1761754199),
(34252, 'Acts 10:39', 'Acts', 10, 39, 'مونږ د هغو ټولو کارونو شاهدان یو چې عیسی د یهودیانو په وطن او اورشلیم کې وکړل. هغوی عیسی په صلیب باندې ځوړند کړ او ویې واژه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_39.mp3', '', 1761754199, 1761754199),
(34253, 'Acts 10:40', 'Acts', 10, 40, 'خو خدای هغه په درېمه ورځ بېرته راژوندی کړ او خلکو ته یې ښکاره کړ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_40.mp3', '', 1761754199, 1761754199),
(34254, 'Acts 10:41', 'Acts', 10, 41, 'ټولو خلکو ته نه، بلکې یوازې هغو شاهدانو ته چې خدای له مخکې نه غوره کړي وو، یعنې مونږ ته چې د هغه د بیا راژوندي کېدلو څخه وروسته مو ورسره وخوړل او وڅښل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_41.mp3', '', 1761754199, 1761754199),
(34255, 'Acts 10:42', 'Acts', 10, 42, 'عیسی مونږ ته حکم کړی چې خلکو ته وعظ وکړو او دا شهادت ورکړو چې دا هغه څوک دی چې خدای په مړو او ژوندیو باندې قاضي ټاکلی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_42.mp3', '', 1761754199, 1761754199),
(34256, 'Acts 10:43', 'Acts', 10, 43, 'د هغه په هکله ټول پیغمبران شاهدي ورکوي او وایي چې هرڅوک چې په هغه باندې ایمان راوړي، نو د هغه په نوم به یې ګناهونه وبخښل شي.» په غیریهودیانو باندې د روح القدس نازلېدل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_43.mp3', '', 1761754199, 1761754199),
(34257, 'Acts 10:44', 'Acts', 10, 44, 'پطروس لا خبرې کولې چې په هغو ټولو خلکو باندې چې د هغه خبرې یې اورېدلې، روح القدس نازل شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts10_verse_44.mp3', '', 1761754199, 1761754199),
